    #[test]
    fn argmax_aux_witness_orientation_and_gap_bits() {
        let mut store = Store::new();
        let x = store.push(vec![
            from_i64(9), from_i64(1), from_i64(9), from_i64(3),
            from_i64(2), from_i64(9), from_i64(1), from_i64(9),
        ]);
        let sel = store.push(vec![]);
        let thr = store.push(vec![]);
        let gate = store.push(vec![]);
        let d1 = store.push(vec![]);
        let d2 = store.push(vec![]);
        let out = store.push_idx(vec![]);
        let ops = vec![Op::Argmax { x, sel, thr, gate, d1, d2, out, m: 2, n: 4 }];
        forward_ops(&mut store, &ops);
        assert_eq!(store.idx[out], vec![0u32, 1u32]);
        let aux = prepare_argmax_aux(&store, &ops).unwrap();
        let descriptor = &aux[0].descriptor;
        assert_eq!(descriptor.len, 8);
        assert_eq!(descriptor.columns, 2 + ARGMAX_D2_BITS + ARGMAX_TIE_BITS);
        let cols = &aux[0].columns;
        assert_eq!(&cols[0][..8], &[
            Goldilocks::ONE, Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO,
            Goldilocks::ZERO, Goldilocks::ONE, Goldilocks::ZERO, Goldilocks::ZERO,
        ]);
        // before_j = 1[j < out_i] is a SUFFIX indicator: row0 out=0 -> none;
        // row1 out=1 -> only j=0.
        assert_eq!(&cols[1][..8], &[
            Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO,
            Goldilocks::ONE, Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO,
        ]);
        // d2 gaps: row0 [0,8,0,6], row1 [7,0,8,0].
        assert_eq!(cols[2 + 3][1], Goldilocks::ONE);
        assert_eq!(cols[2 + 0][4], Goldilocks::ONE);
        assert_eq!(cols[2 + 1][4], Goldilocks::ONE);
        assert_eq!(cols[2 + 2][4], Goldilocks::ONE);
        // tie_gap = d2 - before + sel: row0 [1,8,0,6], row1 [6,1,8,0].
        let tie = 2 + ARGMAX_D2_BITS;
        assert_eq!(cols[tie][0], Goldilocks::ONE); // selected cell tie = 1
        assert_eq!(cols[tie + 3][1], Goldilocks::ONE); // 8 = 1<<3
        assert_eq!(cols[tie + 0][4], Goldilocks::ZERO); // 6 = 110b
        assert_eq!(cols[tie + 1][4], Goldilocks::ONE);
        assert_eq!(cols[tie + 2][4], Goldilocks::ONE);
        assert_eq!(cols[tie][5], Goldilocks::ONE); // selected cell tie = 1
    }

    #[test]
    fn argmax_suffix_kernel_matches_exhaustive_mle() {
        for l in 1usize..=4 {
            let n = 1usize << l;
            for rmask in 0..n {
                let r: Vec<Goldilocks> = (0..l).map(|b| if (rmask >> b) & 1 == 1 { Goldilocks::ONE } else { Goldilocks::ZERO }).collect();
                let eq_r = mle::eq_evals(&r);
                for zmask in 0..n {
                    let z: Vec<Goldilocks> = (0..l).map(|b| if (zmask >> b) & 1 == 1 { Goldilocks::ONE } else { Goldilocks::ZERO }).collect();
                    let eq_z = mle::eq_evals(&z);
                    let mut direct = Goldilocks::ZERO;
                    for j in 0..n {
                        let mut inner = Goldilocks::ZERO;
                        for k in (j + 1)..n { inner = inner + eq_z[k]; }
                        direct = direct + eq_r[j] * inner;
                    }
                    assert_eq!(suffix_kernel_eval(&r, &z), direct, "l={} r={} z={}", l, rmask, zmask);
                    // Coefficient column at the basis index k: C(k) = sum_{j<k} eq(r,j).
                    let mut prefix = Goldilocks::ZERO;
                    for k in 0..n {
                        let mut expect = Goldilocks::ZERO;
                        for j in 0..k { expect = expect + eq_r[j]; }
                        assert_eq!(prefix, expect, "prefix mismatch at k={}", k);
                        prefix = prefix + eq_r[k];
                    }
                }
            }
        }
    }

    #[test]
    fn argmax_known_sel_sums_endpoint_closed_forms() {
        let m = 2usize;
        let n = 4usize;
        let sel = [
            Goldilocks::ONE, Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO,
            Goldilocks::ZERO, Goldilocks::ONE, Goldilocks::ZERO, Goldilocks::ZERO,
        ];
        let before = [
            Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO,
            Goldilocks::ONE, Goldilocks::ZERO, Goldilocks::ZERO, Goldilocks::ZERO,
        ];
        let r_rows = vec![Goldilocks::from_u64(7)];
        let r_col = vec![Goldilocks::from_u64(3), Goldilocks::from_u64(5)];
        let eq_rows = mle::eq_evals(&r_rows);
        let eq_col = mle::eq_evals(&r_col);
        let terms = known_sel_terms();

        // out binding: K(i,j) = eq(r_rows,i) * j.
        let mut known_out = vec![Goldilocks::ZERO; m * n];
        for i in 0..m {
            for j in 0..n {
                known_out[i * n + j] = eq_rows[i] * Goldilocks::from_u64(j as u64);
            }
        }
        let target_out = known_out.iter().zip(sel.iter()).fold(Goldilocks::ZERO, |a, (&k, &s)| a + k * s);
        let out_vec: Vec<Goldilocks> = (0..m).map(|i| Goldilocks::from_u64(if i == 0 { 0 } else { 1 })).collect();
        assert_eq!(target_out, mle::eval(&out_vec, &r_rows));
        let mut tp = Transcript::new(b"argmax-out-binding");
        let (proof, point) = prove_known_sel_sum(&known_out, &sel, target_out, &mut tp);
        let mut tv = Transcript::new(b"argmax-out-binding");
        let (ok, point_v, final_claim) = verify_virtual(&proof, &terms, target_out, 3, &mut tv);
        assert!(ok && point == point_v);
        let (z_j, z_i) = point.split_at(2);
        let known_eval = mle::eq_poly(&r_rows, z_i) * mle_integer(z_j);
        let sel_eval = mle::eval(&sel, &point);
        assert_eq!(final_claim, virtual_eval(&terms, &[known_eval, sel_eval]));

        // before suffix relation: before(r_i,r_j) = sum_{i,k} eq(r_rows,i) C(k) sel(i,k),
        // with C(k) = sum_{j<k} eq(r_col,j).
        let mut coeff = vec![Goldilocks::ZERO; n];
        let mut acc = Goldilocks::ZERO;
        for k in 0..n {
            coeff[k] = acc;
            acc = acc + eq_col[k];
        }
        let mut known_before = vec![Goldilocks::ZERO; m * n];
        for i in 0..m {
            for k in 0..n {
                known_before[i * n + k] = eq_rows[i] * coeff[k];
            }
        }
        let combined: Vec<Goldilocks> = r_col.iter().chain(r_rows.iter()).cloned().collect();
        let target_before = mle::eval(&before, &combined);
        let mut tp2 = Transcript::new(b"argmax-before-binding");
        let (proof2, point2) = prove_known_sel_sum(&known_before, &sel, target_before, &mut tp2);
        let mut tv2 = Transcript::new(b"argmax-before-binding");
        let (ok2, point2_v, final2) = verify_virtual(&proof2, &terms, target_before, 3, &mut tv2);
        assert!(ok2 && point2 == point2_v);
        let (z_k, z_i2) = point2.split_at(2);
        let known2 = mle::eq_poly(&r_rows, z_i2) * suffix_kernel_eval(&r_col, z_k);
        let sel_eval2 = mle::eval(&sel, &point2);
        assert_eq!(final2, virtual_eval(&terms, &[known2, sel_eval2]));
    }

    #[test]
    fn argmax_suffix_kernel_nonboolean_points() {
        // Fixed replayable non-Boolean points; a Boolean-basis-only check cannot
        // rule out accidental higher-degree terms in the closed form.
        let samples: Vec<Vec<u64>> = vec![
            vec![],
            vec![3],
            vec![2, 7],
            vec![5, 1, 9],
            vec![11, 4, 3, 8],
        ];
        for l in 0..=4usize {
            let n = 1usize << l;
            let base: Vec<Goldilocks> = samples[l].iter().map(|&v| Goldilocks::from_u64(v)).collect();
            let sevens: Vec<Goldilocks> = (0..l).map(|_| Goldilocks::from_u64(7)).collect();
            let mut pairs: Vec<(Vec<Goldilocks>, Vec<Goldilocks>)> = Vec::new();
            pairs.push((base.clone(), base.clone())); // r == z
            pairs.push((base.clone(), sevens.clone()));
            pairs.push((sevens.clone(), base.clone()));
            if l > 0 {
                // Highest-bit boundary: equal low bits, differing top bit.
                let mut hi0: Vec<Goldilocks> = (0..l).map(|b| Goldilocks::from_u64(3 + b as u64)).collect();
                let mut hi1 = hi0.clone();
                hi0[l - 1] = Goldilocks::ZERO;
                hi1[l - 1] = Goldilocks::ONE;
                pairs.push((hi0.clone(), hi1.clone()));
                pairs.push((hi1, hi0));
            }
            for (pi, (r, z)) in pairs.into_iter().enumerate() {
                let eq_r = mle::eq_evals(&r);
                let eq_z = mle::eq_evals(&z);
                let mut direct = Goldilocks::ZERO;
                for j in 0..n {
                    for k in (j + 1)..n {
                        direct = direct + eq_r[j] * eq_z[k];
                    }
                }
                assert_eq!(suffix_kernel_eval(&r, &z), direct, "l={} pair={}", l, pi);
                let mut prefix = Goldilocks::ZERO;
                for k in 0..n {
                    let mut expect = Goldilocks::ZERO;
                    for j in 0..k { expect = expect + eq_r[j]; }
                    assert_eq!(prefix, expect, "l={} pair={} k={}", l, pi, k);
                    prefix = prefix + eq_r[k];
                }
            }
        }
    }

    #[test]
    fn committed_argmax_chain_binds_all_outputs_and_tie_rule() {
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let x = store.push(vec![
            from_i64(9), from_i64(1), from_i64(2), from_i64(3), from_i64(4), from_i64(5), from_i64(6), from_i64(7),
            from_i64(5), from_i64(9), from_i64(1), from_i64(9), from_i64(3), from_i64(0), from_i64(2), from_i64(7),
            from_i64(1), from_i64(2), from_i64(3), from_i64(4), from_i64(5), from_i64(6), from_i64(9), from_i64(9),
            from_i64(9), from_i64(1), from_i64(9), from_i64(2), from_i64(3), from_i64(4), from_i64(5), from_i64(6),
        ]);
        let sel = store.push(vec![]);
        let thr = store.push(vec![]);
        let gate = store.push(vec![]);
        let d1 = store.push(vec![]);
        let d2 = store.push(vec![]);
        let out = store.push_idx(vec![]);
        let ops = vec![Op::Argmax { x, sel, thr, gate, d1, d2, out, m: 4, n: 8 }];
        let whir = Whir::with_params(5, 90, 17);
        let cache_dir = std::env::temp_dir().join("zkie-argmax-cache");
        let cached = commit_model_weights(&store, &ops, cache_dir.to_str().unwrap());
        forward_ops(&mut store, &ops);
        assert_eq!(store.idx[out], vec![0u32, 1, 6, 0]);
        let model = TrustedModelManifest::from_offline_commitment(&cached, &store.owned_slices(), &ops)
            .with_index_shapes(&[(out, 4usize)].into());
        let out_vals: Vec<Goldilocks> = store.idx[out].iter().map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let out_key = TensorKey::Index(out).encoded().unwrap();
        let execution = TrustedExecution {
            inputs: [(x, store.get(x).to_vec())].into(),
            outputs: [
                (sel, store.get(sel).to_vec()),
                (thr, store.get(thr).to_vec()),
                (gate, store.get(gate).to_vec()),
                (d1, store.get(d1).to_vec()),
                (d2, store.get(d2).to_vec()),
                (out_key, out_vals),
            ].into(),
        };
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &cached, 0, 0, &PublicStatement::Generic, &model, &execution).unwrap();
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof, &PublicStatement::Generic, &model, &execution));
        let bytes = bincode::serialize(&proof).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(&bytes, &ops, 1, &whir, &PublicStatement::Generic, &model, &execution));
        for id in [sel, thr, gate, d1, d2, out_key] {
            let mut bad = execution.clone();
            bad.outputs.get_mut(&id).unwrap()[0] += Goldilocks::ONE;
            assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof, &PublicStatement::Generic, &model, &bad), "output {} not bound", id);
        }
        let mut forged: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        let mut hit = false;
        for step in &mut forged.reverse.steps {
            if let ReverseReduction::Argmax { proof } = &mut step.reduction {
                proof.aux_values[0] += Goldilocks::ONE;
                hit = true;
            }
        }
        assert!(hit);
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &forged, &PublicStatement::Generic, &model, &execution));
        let mut forged2: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        for step in &mut forged2.reverse.steps {
            if let ReverseReduction::Argmax { proof } = &mut step.reduction { proof.gate_rel.final_evals[2] += Goldilocks::ONE; }
        }
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &forged2, &PublicStatement::Generic, &model, &execution));
        // Forging a relation-virtual endpoint eval on an OUTPUT column must
        // also be rejected (the endpoint check and the leaf binding both
        // catch it).
        let mut forged3: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        for step in &mut forged3.reverse.steps {
            if let ReverseReduction::Argmax { proof } = &mut step.reduction { proof.gate_rel.final_evals[3] += Goldilocks::ONE; }
        }
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &forged3, &PublicStatement::Generic, &model, &execution));
        // Forging the aux sel value at a relation-virtual endpoint must be
        // rejected by the aux opening cross-check.
        let mut forged4: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        for step in &mut forged4.reverse.steps {
            if let ReverseReduction::Argmax { proof } = &mut step.reduction { proof.d1_rel.final_evals[1] += Goldilocks::ONE; }
        }
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &forged4, &PublicStatement::Generic, &model, &execution));
    }

    /// S5-style regression for the Argmax sel_bool virtual: WITHOUT the eq
    /// weighting the virtual only checks the GLOBAL sum Σ sel(1-sel) == 0,
    /// so cross-position cancellation can hide non-boolean entries. This
    /// witness has sel = 1/2 on 8 positions (each contributing +1/4) and
    /// sel = 2 on one (-2): all unweighted sums vanish, yet per-position
    /// booleanity fails — the eq-weighted claim-0 identity must NOT be
    /// certifiable for it. Uses the PRODUCTION terms constructor shared
    /// with prove/verify_reverse_argmax, so dropping the eq weighting in
    /// production turns this test red.
    #[test]
    fn argmax_sel_bool_eq_weighting_rejects_cancelling_nonboolean_witness() {
        let arity = 5usize;
        let len = 1usize << arity;
        let half = Goldilocks::from_u64(2).inverse();
        let mut sel = vec![Goldilocks::ZERO; len];
        for p in 0..8 { sel[p] = half; }
        sel[8] = Goldilocks::from_u64(2);
        let before = vec![Goldilocks::ZERO; len];
        // The unweighted global sums vanish (the pre-fix check passed this):
        let mut unweighted = Goldilocks::ZERO;
        for p in 0..len {
            unweighted = unweighted + sel[p] * (Goldilocks::ONE - sel[p]);
        }
        assert_eq!(unweighted, Goldilocks::ZERO);
        let mut tp = Transcript::new(b"zkie-argmax-selbool-malicious");
        let q: Vec<Goldilocks> = tp.field_vec(arity);
        let eq = mle::eq_evals(&q);
        let g = tp.field();
        let terms = argmax_sel_bool_terms(g);
        assert!(terms.iter().all(|(_, idxs)| idxs.first() == Some(&0usize)),
            "production sel_bool terms must be eq-weighted (index 0)");
        let mles: Vec<&[Goldilocks]> = vec![&eq, &sel, &before];
        let (proof, _z) = prove_virtual(&mles, &terms, Goldilocks::ZERO, &mut tp);
        let mut tv = Transcript::new(b"zkie-argmax-selbool-malicious");
        let qv: Vec<Goldilocks> = tv.field_vec(arity);
        let gv = tv.field();
        assert_eq!(gv, g);
        let (ok, zv, fc) = verify_virtual(&proof, &terms, Goldilocks::ZERO, arity, &mut tv);
        if ok {
            let ev = [mle::eq_poly(&qv, &zv), mle::eval(&sel, &zv), mle::eval(&before, &zv)];
            assert_ne!(fc, virtual_eval(&terms, &ev),
                "a non-boolean witness with vanishing unweighted sums must not certify the zero claim");
        }
    }

    /// Same regression for the Argmax bit_bool virtual: bit = 1/2 on 8
    /// positions and 2 on one makes the unweighted sum vanish while the
    /// per-position booleanity fails. Uses the PRODUCTION terms constructor.
    #[test]
    fn argmax_bit_bool_eq_weighting_rejects_cancelling_nonboolean_witness() {
        let arity = 5usize;
        let len = 1usize << arity;
        let half = Goldilocks::from_u64(2).inverse();
        let mut bit = vec![Goldilocks::ZERO; len];
        for p in 0..8 { bit[p] = half; }
        bit[8] = Goldilocks::from_u64(2);
        let mut unweighted = Goldilocks::ZERO;
        for p in 0..len {
            unweighted = unweighted + bit[p] * (Goldilocks::ONE - bit[p]);
        }
        assert_eq!(unweighted, Goldilocks::ZERO);
        let mut tp = Transcript::new(b"zkie-argmax-bitbool-malicious");
        let q: Vec<Goldilocks> = tp.field_vec(arity);
        let eq = mle::eq_evals(&q);
        let g = tp.field();
        let terms = argmax_bit_bool_terms(g, 1);
        assert!(terms.iter().all(|(_, idxs)| idxs.first() == Some(&0usize)),
            "production bit_bool terms must be eq-weighted (index 0)");
        let mles: Vec<&[Goldilocks]> = vec![&eq, &bit];
        let (proof, _z) = prove_virtual(&mles, &terms, Goldilocks::ZERO, &mut tp);
        let mut tv = Transcript::new(b"zkie-argmax-bitbool-malicious");
        let qv: Vec<Goldilocks> = tv.field_vec(arity);
        let _gv = tv.field();
        let (ok, zv, fc) = verify_virtual(&proof, &terms, Goldilocks::ZERO, arity, &mut tv);
        if ok {
            let ev = [mle::eq_poly(&qv, &zv), mle::eval(&bit, &zv)];
            assert_ne!(fc, virtual_eval(&terms, &ev),
                "a non-boolean bit witness with vanishing unweighted sums must not certify the zero claim");
        }
    }

    #[test]
    fn committed_transpose_matmul_binds_permuted_input() {
        let mut store = Store::new();
        let x = store.push((0..8).map(|i| from_i64(i as i64)).collect());
        let transposed = store.push(vec![]);
        let w = store.push(vec![from_i64(1), from_i64(0), from_i64(0), from_i64(1)]);
        let out = store.push(vec![]);
        let ops = vec![Op::Transpose { x, out: transposed, m: 2, k: 4 }, Op::MatMul { a: transposed, b: w, c: out, m: 4, k: 2, n: 2 }];
        let path = std::env::temp_dir().join("zkie-transpose-chain");
        let cache = commit_model_weights(&store, &ops, path.to_str().unwrap());
        let model = TrustedModelManifest::from_offline_commitment(&cache, &store.owned_slices(), &ops);
        let expected: Vec<_> = [0,4,1,5,2,6,3,7].into_iter().map(from_i64).collect();
        let execution = TrustedExecution { inputs: [(x, store.get(x).to_vec())].into(), outputs: [(out, expected)].into() };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, 90, 17);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 2, &whir, &cache, 0, 0, &PublicStatement::Generic, &model, &execution).unwrap();
        assert!(verify_committed_shard_dag_bound(&ops, 2, &whir, &proof, &PublicStatement::Generic, &model, &execution));
        let mut bad = execution.clone();
        bad.inputs.get_mut(&x).unwrap()[0] += Goldilocks::ONE;
        assert!(!verify_committed_shard_dag_bound(&ops, 2, &whir, &proof, &PublicStatement::Generic, &model, &bad));
    }

    #[test]
    fn reverse_gelu_index_preserves_clamp_boundaries_and_negative_offset() {
        let input: Vec<_> = [-5, -2, -1, 1, 2, 3, 4, 5].into_iter().map(from_i64).collect();
        let point = vec![Goldilocks::from_u64(2), Goldilocks::from_u64(3), Goldilocks::from_u64(4)];
        for (offset, expected) in [
            (2, vec![0, 0, 1, 3, 3, 3, 3, 3]),
            (-2, vec![0, 0, 0, 0, 0, 1, 2, 3]),
        ] {
            let expected: Vec<_> = expected.into_iter().map(from_i64).collect();
            let value = mle::eval(&expected, &point);
            let aux = build_gelu_range_aux(&input, 0, input.len(),
                input.len().trailing_zeros().max(5) as usize).unwrap();
            let aux_desc = aux.descriptor.clone();
            let mut tp = Transcript::new(b"gelu-boundaries");
            let (proof, _) = prove_reverse_gelu_index(&input, offset, 4, &point, value, aux, &mut tp).unwrap();
            let mut tv = Transcript::new(b"gelu-boundaries");
            let leaves = verify_reverse_gelu_index(offset, 4, &point, value, Some(&aux_desc), &proof, &mut tv).unwrap();
            assert!(leaves.iter().all(|(p, v)| mle::eval(&input, p) == *v));
        }
    }

    fn gelu_direct_point(arity: usize) -> Vec<Goldilocks> {
        (0..arity).map(|b| Goldilocks::from_u64((5 * b + 2) as u64)).collect()
    }

    fn gelu_direct_expected(input: &[Goldilocks], offset: i64, table_len: usize) -> Vec<Goldilocks> {
        let limit = (table_len - 1) as i64;
        input.iter().map(|&x| {
            let w = to_i64(x) + offset;
            let high = w - limit;
            from_i64(w.max(0) - high.max(0))
        }).collect()
    }

    fn gelu_direct_roundtrip(input: &[Goldilocks], offset: i64, table_len: usize) -> bool {
        let arity = input.len().trailing_zeros() as usize;
        let point = gelu_direct_point(arity);
        let expected = gelu_direct_expected(input, offset, table_len);
        let value = mle::eval(&expected, &point);
        let aux = build_gelu_range_aux(input, 0, input.len(),
            input.len().trailing_zeros().max(5) as usize).unwrap();
        let desc = aux.descriptor.clone();
        let (proof, _) = prove_reverse_gelu_index(input, offset, table_len, &point, value, aux,
            &mut Transcript::new(b"gelu-bounds")).unwrap();
        let leaves = verify_reverse_gelu_index(offset, table_len, &point, value, Some(&desc), &proof,
            &mut Transcript::new(b"gelu-bounds")).unwrap();
        leaves.iter().all(|(p, v)| mle::eval(input, p) == *v)
    }

    /// Project ② step 1: the 25-bit signed domain [-2^24, 2^24) is accepted
    /// at its inclusive edges, and the new table_len/offset contract allows
    /// table_len = 2^24 with offset 0 or 2^24 on in-range inputs.
    #[test]
    fn gelu_index_signed_domain_boundaries_roundtrip() {
        let bound = 1i64 << 24;
        // table_len = 1: w = high = x, so the ±2^24 domain edges are direct.
        let edge: Vec<_> = [-bound, -bound + 1, -1, 0, 1, 2, bound - 1, 3]
            .into_iter().map(from_i64).collect();
        assert!(gelu_direct_roundtrip(&edge, 0, 1), "±2^24 edges must prove");
        // table_len = 2^24: w and high stay in range for these inputs.
        let big_table: Vec<_> = [0, 1, 2, bound - 1, -1, 0, 1, 2]
            .into_iter().map(from_i64).collect();
        assert!(gelu_direct_roundtrip(&big_table, 0, 1usize << 24), "table_len=2^24");
        // offset = 2^24 (contract edge): x < 0 keeps w = x + 2^24 in range.
        let off_edge: Vec<_> = [-bound, -bound + 1, -3, -2, -1, -1, -2, -3]
            .into_iter().map(from_i64).collect();
        assert!(gelu_direct_roundtrip(&off_edge, bound, 1), "offset=2^24");
        let both: Vec<_> = [-bound, -bound + 1, -3, -2, -1, -1, -2, -3]
            .into_iter().map(from_i64).collect();
        assert!(gelu_direct_roundtrip(&both, bound, 1usize << 24), "2^24 table + 2^24 offset");
    }

    /// Project ② step 1 negatives: domain wrap (to_i64(x) outside the signed
    /// domain while x + offset mod p lands in the ReLU domain), out-of-domain
    /// inputs, the table_len/offset contract, and a forged range x eval. The
    /// prover fails closed on the 25-bit witness; the verifier rejects forged
    /// range data through the precommitted aux opening and the x-range
    /// virtual identity.
    #[test]
    fn gelu_index_domain_wrap_and_contract_rejected() {
        let bound = 1i64 << 24;
        let good: Vec<_> = (0..8).map(from_i64).collect();
        let point = gelu_direct_point(3);
        let value = mle::eval(&gelu_direct_expected(&good, 0, 1), &point);
        let aux = build_gelu_range_aux(&good, 0, 8, 5).unwrap();
        let desc = aux.descriptor.clone();
        let (proof, _) = prove_reverse_gelu_index(&good, 0, 1, &point, value, aux,
            &mut Transcript::new(b"gelu-neg")).unwrap();
        assert!(verify_reverse_gelu_index(0, 1, &point, value, Some(&desc), &proof,
            &mut Transcript::new(b"gelu-neg")).is_some());

        // Contract: non-power-of-two / > 2^24 table_len and |offset| > 2^24.
        for (off, tl) in [(0i64, 3usize), (0, 1usize << 25), (bound + 1, 1)] {
            let aux2 = build_gelu_range_aux(&good, 0, 8, 5).unwrap();
            assert!(prove_reverse_gelu_index(&good, off, tl, &point, value, aux2,
                &mut Transcript::new(b"gelu-neg")).is_none(),
                "prover must reject contract violation off={off} tl={tl}");
            assert!(verify_reverse_gelu_index(off, tl, &point, value, Some(&desc), &proof,
                &mut Transcript::new(b"gelu-neg")).is_none(),
                "verifier must reject contract violation off={off} tl={tl}");
        }

        // Out-of-domain signed edges: -2^24 - 1 and 2^24 cannot be decomposed
        // into 25 bits (x + 2^24 outside [0, 2^25)).
        let mut low = good.clone(); low[0] = from_i64(-bound - 1);
        assert!(build_gelu_range_aux(&low, 0, 8, 5).is_none());
        let mut high = good.clone(); high[0] = from_i64(bound);
        assert!(build_gelu_range_aux(&high, 0, 8, 5).is_none());
        // With a 25-bit witness for a different input, the prover's bit
        // consistency check still rejects.
        let aux3 = build_gelu_range_aux(&good, 0, 8, 5).unwrap();
        assert!(prove_reverse_gelu_index(&low, 0, 1, &point, value, aux3,
            &mut Transcript::new(b"gelu-neg")).is_none());

        // Field-wrap attack: x = -(2^24+1) (to_i64 out of domain) but
        // x + offset mod p = 0 with offset = 2^24+1, inside the ReLU domain.
        let wrap = from_i64(-bound - 1);
        let wrap_off = bound + 1;
        assert_eq!(to_i64(wrap) + wrap_off, 0, "w lands in the ReLU domain");
        let mut wrap_input = good.clone(); wrap_input[0] = wrap;
        assert!(build_gelu_range_aux(&wrap_input, 0, 8, 5).is_none(),
            "wrap input has no 25-bit x witness");
        let aux4 = build_gelu_range_aux(&good, 0, 8, 5).unwrap();
        assert!(prove_reverse_gelu_index(&wrap_input, wrap_off, 1, &point, value, aux4,
            &mut Transcript::new(b"gelu-neg")).is_none(),
            "wrap attack must fail closed at the x-range witness");

        // Verifier side: a forged x range eval is rejected by the aux-opening
        // / range virtual binding (the precommitted bits cannot be re-pointed
        // at a wrapped x).
        let mut forged = proof;
        forged.x_range.final_evals[1] += Goldilocks::ONE;
        assert!(verify_reverse_gelu_index(0, 1, &point, value, Some(&desc), &forged,
            &mut Transcript::new(b"gelu-neg")).is_none(),
            "forged range x eval must be rejected");
    }

    /// Project ② step 1: a bound GeluIndex op with the real silu-domain
    /// parameters (table_len = 2^24, offset = 2^23) proves and verifies, and
    /// an out-of-domain input fails closed at the precommitted 25-bit x
    /// witness.
    #[test]
    fn gelu_index_big_table_bound_roundtrip_and_oob_rejected() {
        use zkie_core::pcs::whir::Whir;
        let mut store = Store::new();
        let xv: Vec<Goldilocks> = [0i64, (1 << 23) - 1, -(1 << 23), 1 << 22, -(1 << 22), 1, -1, 2]
            .into_iter().map(from_i64).collect();
        let x = store.push(xv.clone());
        let idx = store.push_idx(vec![]);
        let ops = vec![Op::GeluIndex { x, out: idx, offset: 1 << 23, table_len: 1 << 24 }];
        forward_ops(&mut store, &ops);
        let model = TrustedModelManifest::from_offline_commitment(&[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx, 8usize)].into());
        let idx_key = TensorKey::Index(idx).encoded().unwrap();
        let idx_vals: Vec<Goldilocks> = store.idx[idx].iter().map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let execution = TrustedExecution {
            inputs: [(x, xv.clone())].into(),
            outputs: [(idx_key, idx_vals.clone())].into(),
        };
        let whir = Whir::with_params(5, 90, 17);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("2^24 GeluIndex bound proof");
        assert!(proof.aux.iter().any(|a| a.role == AuxRole::GeluIndexXRange));
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof,
            &PublicStatement::Generic, &model, &execution));
        // Byte determinism for the 25-bit GeluIndex proof path.
        let bytes1 = bincode::serialize(&proof).unwrap();
        let proof2 = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model, &execution).expect("repeat 2^24 GeluIndex proof");
        assert_eq!(bytes1, bincode::serialize(&proof2).unwrap(),
            "GeluIndex proof bytes must be deterministic");
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof2,
            &PublicStatement::Generic, &model, &execution));

        // Out-of-domain input: -2^24-1 has no 25-bit x witness; the bound
        // prover must fail closed before producing a proof.
        let mut store2 = Store::new();
        let mut bad_xv = xv.clone(); bad_xv[0] = from_i64(-(1 << 24) - 1);
        let x2 = store2.push(bad_xv.clone());
        let idx2 = store2.push_idx(vec![]);
        let ops2 = vec![Op::GeluIndex { x: x2, out: idx2, offset: 1 << 23, table_len: 1 << 24 }];
        forward_ops(&mut store2, &ops2);
        let model2 = TrustedModelManifest::from_offline_commitment(&[], &store2.owned_slices(), &ops2)
            .with_index_shapes(&[(idx2, 8usize)].into());
        let idx2_key = TensorKey::Index(idx2).encoded().unwrap();
        let idx2_vals: Vec<Goldilocks> = store2.idx[idx2].iter().map(|&v| Goldilocks::from_u64(v as u64)).collect();
        let execution2 = TrustedExecution {
            inputs: [(x2, bad_xv)].into(),
            outputs: [(idx2_key, idx2_vals)].into(),
        };
        assert!(prove_committed_shard_dag_bound(&mut store2, &ops2, 1, &whir, &[], 0, 0,
            &PublicStatement::Generic, &model2, &execution2).is_none(),
            "out-of-domain GeluIndex input must fail closed");
    }

    #[test]
    fn committed_projection_gelu_lookup_projection_residual_chain() {
        let mut store = Store::new();
        let x = store.push(vec![from_i64(-12), from_i64(-4), from_i64(4), from_i64(12)]);
        let w = store.push(vec![from_i64(1), from_i64(0), from_i64(0), from_i64(1)]);
        let bias = store.push(vec![Goldilocks::ZERO; 4]);
        let p1 = store.push(vec![]);
        let r1 = store.push(vec![]);
        let table = store.push(vec![from_i64(1), from_i64(3), from_i64(5), from_i64(7)]);
        let lookup = store.push(vec![]);
        let p2 = store.push(vec![]);
        let r2 = store.push(vec![]);
        let out = store.push(vec![]);
        let idx = store.push_idx(vec![]);
        assert_eq!(idx, x);
        let ops = vec![
            Op::Projection { x, w, bias, out: p1, rem: r1, m: 2, k: 2, n: 2, shift: 3 },
            Op::GeluIndex { x: p1, out: idx, offset: 2, table_len: 4 },
            Op::Lookup { idx, out: lookup, table },
            Op::Projection { x: lookup, w, bias, out: p2, rem: r2, m: 2, k: 2, n: 2, shift: 1 },
            Op::Add { a: p2, b: x, c: out },
        ];
        let whir = zkie_core::pcs::whir::Whir::with_params(5, 90, 17);
        let path = std::env::temp_dir().join("zkie-bound-gelu-chain");
        let cache = commit_model_weights(&store, &ops, path.to_str().unwrap());
        let model = TrustedModelManifest::from_offline_commitment(&cache, &store.owned_slices(), &ops).with_index_shapes(&[(idx, 4usize)].into());
        let execution = TrustedExecution { inputs: [(x, store.get(x).to_vec())].into(), outputs: [(out, vec![from_i64(-10), from_i64(-1), from_i64(8), from_i64(16)])].into() };
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 5, &whir, &cache, 0, 0, &PublicStatement::Generic, &model, &execution).unwrap();
        let gxr = proof.aux.iter().find(|a| a.op_index == 1 && a.role == AuxRole::GeluIndexXRange)
            .expect("GeluIndexXRange aux must be precommitted");
        assert_eq!((gxr.len, gxr.arity, gxr.columns), (4usize, 5usize, GELU_XRANGE_BITS));
        assert!(verify_committed_shard_dag_bound(&ops, 5, &whir, &proof, &PublicStatement::Generic, &model, &execution));
        let bytes = bincode::serialize(&proof).unwrap();
        assert!(verify_committed_shard_dag_bound_bytes(&bytes, &ops, 5, &whir, &PublicStatement::Generic, &model, &execution));
        let mut forged: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        for step in &mut forged.reverse.steps {
            if let ReverseReduction::Lookup { proof: p } = &mut step.reduction { p.output_index += Goldilocks::ONE; }
        }
        assert!(!verify_committed_shard_dag_bound(&ops, 5, &whir, &forged, &PublicStatement::Generic, &model, &execution));
        let mut missing: BoundExecutionProof = bincode::deserialize(&bytes).unwrap();
        missing.aux.pop();
        assert!(!verify_committed_shard_dag_bound(&ops, 5, &whir, &missing, &PublicStatement::Generic, &model, &execution));
        let mut bad = execution.clone();
        bad.outputs.get_mut(&out).unwrap()[0] += Goldilocks::ONE;
        assert!(!verify_committed_shard_dag_bound(&ops, 5, &whir, &proof, &PublicStatement::Generic, &model, &bad));
    }

    #[test]
    fn lookup_rejects_forged_padded_identity_row() {
        fn make_aux(op_index: usize, role: AuxRole, len: usize, columns: Vec<Vec<Goldilocks>>) -> PreparedAux {
            let arity = 5usize;
            let count = columns.len();
            let vars = (count * 32).next_power_of_two().trailing_zeros() as usize;
            let pow = zkie_core::pcs::whir::Whir::required_pow_bits(vars, 90);
            let whir = zkie_core::pcs::whir::Whir::with_params(arity, 90, pow);
            let refs: Vec<&[Goldilocks]> = columns.iter().map(Vec::as_slice).collect();
            let (commitment, prover_data, protocol, whir) = whir.commit_batch(&refs);
            PreparedAux { descriptor: AuxDescriptor { op_index, role, len, arity, columns: count, commitment }, columns, prover_data, protocol, whir }
        }
        let mut store = Store::new();
        let table = store.push(vec![from_i64(0), from_i64(1), from_i64(2)]);
        let idx = store.push_idx(vec![3]);
        let out = store.push(vec![from_i64(3)]);
        let ops = vec![Op::Lookup { idx, out, table }];
        let model = TrustedModelManifest::from_offline_commitment(&[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx, 1usize)].into());
        let mut x = vec![Goldilocks::ZERO; 32]; x[0] = from_i64(3);
        let mut y = vec![Goldilocks::ZERO; 32]; y[0] = from_i64(3);
        let mut m = vec![Goldilocks::ZERO; 32]; m[3] = Goldilocks::ONE;
        let pairs = make_aux(0, AuxRole::LookupPairs, 1, vec![x, y]);
        let mult = make_aux(0, AuxRole::LookupMultiplicity, 3, vec![m]);
        let pair_desc = pairs.descriptor.clone();
        let mult_desc = mult.descriptor.clone();
        let mut prover = Transcript::new(b"padded-identity-forgery");
        let (proof, _, _) = prove_reverse_lookup(&store, &ops[0], &[], from_i64(3), pairs, mult, &model, false, None, &mut prover).unwrap();
        let mut verifier = Transcript::new(b"padded-identity-forgery");
        assert!(verify_reverse_lookup(&ops[0], &[], from_i64(3), &pair_desc, &mult_desc, &model, false, None, &proof, &mut verifier).is_none());
    }

    #[test]
    fn committed_lookup_binds_typed_index_and_table() {
        let mut store = Store::new();
        let table = store.push(vec![from_i64(7), from_i64(3), from_i64(9), from_i64(5)]);
        let idx = store.push_idx(vec![1, 0, 3, 2]);
        assert_eq!(idx, table);
        let out = store.push(vec![]);
        let ops = vec![Op::Lookup { idx, out, table }];
        let model = TrustedModelManifest::from_offline_commitment(&[], &store.owned_slices(), &ops)
            .with_index_shapes(&[(idx, 4usize)].into());
        let index_key = TensorKey::Index(idx).encoded().unwrap();
        let execution = TrustedExecution { inputs: [(index_key, vec![from_i64(1), from_i64(0), from_i64(3), from_i64(2)])].into(), outputs: [(out, vec![from_i64(3), from_i64(7), from_i64(5), from_i64(9)])].into() };
        let whir = zkie_core::pcs::whir::Whir::with_params(5, 90, 17);
        let proof = prove_committed_shard_dag_bound(&mut store, &ops, 1, &whir, &[], 0, 0, &PublicStatement::Generic, &model, &execution).unwrap();
        assert!(verify_committed_shard_dag_bound(&ops, 1, &whir, &proof, &PublicStatement::Generic, &model, &execution));
        let mut wrong_namespace = execution.clone();
        let values = wrong_namespace.inputs.remove(&index_key).unwrap();
        wrong_namespace.inputs.insert(TensorKey::Field(idx).encoded().unwrap(), values);
        assert!(!verify_committed_shard_dag_bound(&ops, 1, &whir, &proof, &PublicStatement::Generic, &model, &wrong_namespace));
    }

